package com.tmevolut.ecommerce.api.controller;
import com.tmevolut.ecommerce.api.dto.*; import com.tmevolut.ecommerce.api.service.ProdutoService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@Tag(name="Produtos") @RestController @RequestMapping("/api/v1/produtos")
public class ProdutoController { private final ProdutoService service; public ProdutoController(ProdutoService service){this.service=service;}
@GetMapping public Page<ProdutoResponse> listar(@RequestParam(required=false) String nome, Pageable pageable){return service.listar(nome,pageable);} @GetMapping("/{id}") public ProdutoResponse buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<ProdutoResponse> criar(@Valid @RequestBody ProdutoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.criar(r));} @PutMapping("/{id}") public ProdutoResponse atualizar(@PathVariable Long id,@Valid @RequestBody ProdutoRequest r){return service.atualizar(id,r);} @PatchMapping("/{id}") public ProdutoResponse patch(@PathVariable Long id,@RequestBody ProdutoPatchRequest r){return service.atualizarParcial(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> remover(@PathVariable Long id){service.remover(id);return ResponseEntity.noContent().build();}}
